-- ==============================================================================\n-- INCREMENTAL TASKS\n-- ==============================================================================\n-- RAW_DATA -> STREAM -> TASK -> CLEAN_DATA\n--\n-- Tasks run every minute when their stream contains data.\n-- INSERT stream records are processed so updates represented as DELETE + INSERT\n-- use the latest inserted row image.\n\nUSE DATABASE MARKETING_CAMP_ANALYSIS;\nUSE SCHEMA CLEAN_DATA;\n\n-- CUSTOMER JOURNEY\nCREATE OR REPLACE TASK CLEAN_DATA.CUSTOMER_JOURNEY_TASK\nWAREHOUSE = MARKETING_CAMP_WH\nSCHEDULE = '1 MINUTE'\nWHEN SYSTEM$STREAM_HAS_DATA('RAW_DATA.CUSTOMER_JOURNEY_STREAM')\nAS\nMERGE INTO CLEAN_DATA.CUSTOMER_JOURNEY AS TARGET\nUSING\n(\n    WITH STREAM_DATA AS\n    (\n        SELECT JOURNEYID, CUSTOMERID, PRODUCTID, VISITDATE,\n               UPPER(TRIM(STAGE)) AS STAGE,\n               TRIM(ACTION) AS ACTION,\n               DURATION, METADATA$ACTION, METADATA$ISUPDATE\n        FROM RAW_DATA.CUSTOMER_JOURNEY_STREAM\n        WHERE METADATA$ACTION = 'INSERT'\n    ),\n    DEDUPLICATED AS\n    (\n        SELECT JOURNEYID, CUSTOMERID, PRODUCTID, VISITDATE, STAGE, ACTION, DURATION,\n               ROW_NUMBER() OVER(PARTITION BY CUSTOMERID, PRODUCTID, VISITDATE, STAGE, ACTION ORDER BY JOURNEYID) AS ROW_NUM\n        FROM STREAM_DATA\n    ),\n    AVG_DURATION AS\n    (\n        SELECT VISITDATE, AVG(DURATION) AS AVG_DURATION\n        FROM CLEAN_DATA.CUSTOMER_JOURNEY\n        GROUP BY VISITDATE\n    )\n    SELECT D.JOURNEYID, D.CUSTOMERID, D.PRODUCTID, D.VISITDATE, D.STAGE, D.ACTION,\n           COALESCE(TRY_TO_NUMBER(NULLIF(TRIM(D.DURATION), 'NULL')), A.AVG_DURATION) AS DURATION\n    FROM DEDUPLICATED D\n    LEFT JOIN AVG_DURATION A ON D.VISITDATE = A.VISITDATE\n    WHERE D.ROW_NUM = 1\n) AS SOURCE\nON TARGET.JOURNEYID = SOURCE.JOURNEYID\nWHEN MATCHED THEN UPDATE SET\n    TARGET.CUSTOMERID = SOURCE.CUSTOMERID,\n    TARGET.PRODUCTID = SOURCE.PRODUCTID,\n    TARGET.VISITDATE = SOURCE.VISITDATE,\n    TARGET.STAGE = SOURCE.STAGE,\n    TARGET.ACTION = SOURCE.ACTION,\n    TARGET.DURATION = SOURCE.DURATION\nWHEN NOT MATCHED THEN INSERT\n    (JOURNEYID, CUSTOMERID, PRODUCTID, VISITDATE, STAGE, ACTION, DURATION)\nVALUES\n    (SOURCE.JOURNEYID, SOURCE.CUSTOMERID, SOURCE.PRODUCTID, SOURCE.VISITDATE, SOURCE.STAGE, SOURCE.ACTION, SOURCE.DURATION);\n\n-- CUSTOMERS\nCREATE OR REPLACE TASK CLEAN_DATA.CUSTOMERS_TASK\nWAREHOUSE = MARKETING_CAMP_WH\nSCHEDULE = '1 MINUTE'\nWHEN SYSTEM$STREAM_HAS_DATA('RAW_DATA.CUSTOMERS_STREAM')\nAS\nMERGE INTO CLEAN_DATA.CUSTOMERS AS TARGET\nUSING\n(\n    SELECT CUSTOMER_ID, CUSTOMER_NAME, EMAIL, GENDER, AGE, GEOGRAPHY_ID\n    FROM RAW_DATA.CUSTOMERS_STREAM\n    WHERE METADATA$ACTION = 'INSERT'\n) AS SOURCE\nON TARGET.CUSTOMER_ID = SOURCE.CUSTOMER_ID\nWHEN MATCHED THEN UPDATE ALL BY NAME\nWHEN NOT MATCHED THEN INSERT ALL BY NAME;\n\n-- GEOGRAPHY\nCREATE OR REPLACE TASK CLEAN_DATA.GEOGRAPHY_TASK\nWAREHOUSE = MARKETING_CAMP_WH\nSCHEDULE = '1 MINUTE'\nWHEN SYSTEM$STREAM_HAS_DATA('RAW_DATA.GEOGRAPHY_STREAM')\nAS\nMERGE INTO CLEAN_DATA.GEOGRAPHY AS TARGET\nUSING\n(\n    SELECT GEOGRAPHY_ID, COUNTRY, CITY\n    FROM RAW_DATA.GEOGRAPHY_STREAM\n    WHERE METADATA$ACTION = 'INSERT'\n) AS SOURCE\nON TARGET.GEOGRAPHY_ID = SOURCE.GEOGRAPHY_ID\nWHEN MATCHED THEN UPDATE ALL BY NAME\nWHEN NOT MATCHED THEN INSERT ALL BY NAME;\n\n-- PRODUCTS\nCREATE OR REPLACE TASK CLEAN_DATA.PRODUCTS_TASK\nWAREHOUSE = MARKETING_CAMP_WH\nSCHEDULE = '1 MINUTE'\nWHEN SYSTEM$STREAM_HAS_DATA('RAW_DATA.PRODUCTS_STREAM')\nAS\nMERGE INTO CLEAN_DATA.PRODUCTS AS TARGET\nUSING\n(\n    SELECT PRODUCT_ID, PRODUCT_NAME, PRICE, CATEGORY,\n           CASE\n               WHEN PRICE < 50 THEN 'Low'\n               WHEN PRICE BETWEEN 50 AND 200 THEN 'Medium'\n               WHEN PRICE > 200 THEN 'High'\n           END AS PRICE_CATEGORY\n    FROM RAW_DATA.PRODUCTS_STREAM\n    WHERE METADATA$ACTION = 'INSERT'\n) AS SOURCE\nON TARGET.PRODUCT_ID = SOURCE.PRODUCT_ID\nWHEN MATCHED THEN UPDATE ALL BY NAME\nWHEN NOT MATCHED THEN INSERT ALL BY NAME;\n\n-- CUSTOMERS ENGAGEMENT\nCREATE OR REPLACE TASK CLEAN_DATA.ENGAGEMENT_TASK\nWAREHOUSE = MARKETING_CAMP_WH\nSCHEDULE = '1 MINUTE'\nWHEN SYSTEM$STREAM_HAS_DATA('RAW_DATA.CUSTOMER_ENGAGEMENT_STREAM')\nAS\nMERGE INTO CLEAN_DATA.CUSTOMERS_ENGAGEMENT AS TARGET\nUSING\n(\n    SELECT ENGAGEMENT_ID, CONTENT_ID, CAMPAIGN_ID, PRODUCT_ID,\n           REPLACE(UPPER(CONTENT_TYPE), 'SOCIALMEDIA', 'SOCIAL MEDIA') AS CONTENT_TYPE,\n           TRY_TO_NUMBER(LEFT(VIEWS_CLICKS, CHARINDEX('-', VIEWS_CLICKS) - 1)) AS VIEWS,\n           TRY_TO_NUMBER(RIGHT(VIEWS_CLICKS, LEN(VIEWS_CLICKS) - CHARINDEX('-', VIEWS_CLICKS))) AS CLICKS,\n           LIKES, ENGAGEMENT_DATE\n    FROM RAW_DATA.CUSTOMER_ENGAGEMENT_STREAM\n    WHERE METADATA$ACTION = 'INSERT'\n      AND UPPER(TRIM(CONTENT_TYPE)) <> 'NEWSLETTER'\n) AS SOURCE\nON TARGET.ENGAGEMENT_ID = SOURCE.ENGAGEMENT_ID\nWHEN MATCHED THEN UPDATE ALL BY NAME\nWHEN NOT MATCHED THEN INSERT ALL BY NAME;\n\nSHOW TASKS IN SCHEMA CLEAN_DATA;\n\n-- Resume only the tasks that have been validated in the Snowflake environment.\n-- ALTER TASK CLEAN_DATA.CUSTOMER_JOURNEY_TASK RESUME;\n-- ALTER TASK CLEAN_DATA.CUSTOMERS_TASK RESUME;\n-- ALTER TASK CLEAN_DATA.GEOGRAPHY_TASK RESUME;\n-- ALTER TASK CLEAN_DATA.PRODUCTS_TASK RESUME;\n-- ALTER TASK CLEAN_DATA.ENGAGEMENT_TASK RESUME;\n